 using Microsoft.ML;
 using Microsoft.ML.Data;
 using Microsoft.Extensions.ML;

 // --- Train the model at startup ---
 var mlContext = new MLContext(seed: 42);

 var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
 IDataView data = mlContext.Data.LoadFromTextFile<CustomerInput>(dataPath, hasHeader: true, separatorChar: ',');

 var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2);

 var pipeline = mlContext.Transforms.CustomMapping<CustomerInput, CustomerMapped>(
         (input, output) => output.Label = string.Equals(input.Churned, "Yes", StringComparison.OrdinalIgnoreCase),
         contractName: "ChurnMapping")
     .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerInput.Region)))
     .Append(mlContext.Transforms.Concatenate("Features",
         nameof(CustomerInput.Age),
         nameof(CustomerInput.Income),
         "RegionEncoded",
         nameof(CustomerInput.PurchaseHistory)))
     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
         labelColumnName: "Label", featureColumnName: "Features"));

 var model = pipeline.Fit(split.TrainSet);

 try
 {
     var predictions = model.Transform(split.TestSet);
     var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
     Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
 }
 catch (ArgumentOutOfRangeException)
 {
     Console.WriteLine("Model trained — test set too small for meaningful metrics. Add more data for evaluation.");
 }

 var modelPath = Path.Combine(AppContext.BaseDirectory, "churn_model.zip");
 mlContext.Model.Save(model, data.Schema, modelPath);

 // --- Set up the web API ---
 var builder = WebApplication.CreateBuilder(args);

 builder.Services.AddPredictionEnginePool<CustomerInput, ChurnPrediction>()
     .FromFile(modelName: "ChurnModel", filePath: modelPath, watchForChanges: false);

 var app = builder.Build();

 app.MapGet("/", () => "Churn Predictor API — POST /predict with customer data");

 app.MapPost("/predict", (PredictRequest request,
     Microsoft.Extensions.ML.PredictionEnginePool<CustomerInput, ChurnPrediction> pool) =>
 {
     var input = new CustomerInput
     {
